import json,subprocess,http.client,os
from pathlib import Path
root=Path('/srv/projects')
old=['/etc/fadego-staging','/etc/pink-iptv']
expected_roots=['Codex','VPS','fadego','iptvpn-bot','lowcost-europa','pink-iptv','skill-universal','telegram-robot-leads']
new={
'fadego':['app.env','send-closed.env'],
'pink-iptv':['backend.env','secrets.env','vpn.env']
}
services=['ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads']
def status(port):
 try:
  conn=http.client.HTTPConnection('127.0.0.1',port,timeout=8)
  conn.request('GET','/',headers={'Host':'127.0.0.1'})
  code=conn.getresponse().status
  conn.close()
  return code
 except Exception as e:return type(e).__name__
out={'audit':'FADEGO_PINK_POST_CONNECTBOT_READBACK','read_only':True,'old_directories':{},'private_files':{},'services':{},'project_roots':[],'vault_preserved':False,'vault_backup_active':False,'archived_reviewed_exists':False,'http':{},'units_private':{},'pass':False}
for oldpath in old:
 p=Path(oldpath)
 out['old_directories'][oldpath]={'exists':p.exists(),'is_symlink':p.is_symlink()}
for project,files in new.items():
 out['private_files'][project]={f:(root/project/'private/systemd-env'/f).is_file() and not (root/project/'private/systemd-env'/f).is_symlink() for f in files}
for service in services:
 p=subprocess.run(['systemctl','is-active',service],capture_output=True,text=True,timeout=10)
 out['services'][service]=p.stdout.strip()
out['project_roots']=sorted(x.name for x in root.iterdir() if x.is_dir() and not x.is_symlink())
out['archived_reviewed_exists']=(root/'fadego/archive/reviewed-etc-fadego-staging-20261104').is_dir()
out['vault_preserved']=Path('/root/project-secrets').is_dir()
out['vault_backup_active']=subprocess.run(['systemctl','is-active','--quiet','project-secrets-offsite-backup.timer'],capture_output=True,timeout=9).returncode==0
out['http']={'fadego':status(3100),'pink':status(8010)}
for unit in ('fadego-staging','pink-iptv-backend'):
 cat=subprocess.run(['systemctl','cat',unit],capture_output=True,text=True,timeout=10)
 active_lines=[s.strip() for s in cat.stdout.splitlines() if s.strip().startswith('EnvironmentFile=')]
 out['units_private'][unit]={'paths':active_lines,'old_paths_absent':not any('/etc/fadego-staging/' in s or '/etc/pink-iptv/' in s for s in active_lines)}
pass_all=all(not v['exists'] and not v['is_symlink'] for v in out['old_directories'].values())
pass_all &= all(all(d.values()) for d in out['private_files'].values())
pass_all &= all(v=='active' for v in out['services'].values())
pass_all &= out['project_roots']==expected_roots
pass_all &= out['archived_reviewed_exists'] and out['vault_preserved'] and out['vault_backup_active']
pass_all &= out['http']=={'fadego':200,'pink':404}
pass_all &= all(x['old_paths_absent'] for x in out['units_private'].values())
out['pass']=bool(pass_all)
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
if not pass_all:raise SystemExit(3)
